DROP POLICY "engagement_entry_write" ON "engagement_entries" CASCADE;--> statement-breakpoint
CREATE POLICY "engagement_entry_create" ON "engagement_entries" AS PERMISSIVE FOR INSERT TO public WITH CHECK (exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.organization_id="engagement_entries"."organization_id" and e.project_id="engagement_entries"."project_id" and (exists(select 1 from memberships m where m.organization_id=e.organization_id and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member')) or (e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status in ('Active') and e.payload->>'contractStatus'='Confirmed' and e.payload->>'companyAgreed'='true' and e.payload->>'expertAgreed'='true' and e.payload->>'conflictStatus'='Cleared' and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status='Verified') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now())))) and exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.status='Active') and "engagement_entries"."author_id"=(select current_setting('borderless.user_id',true)));--> statement-breakpoint
CREATE POLICY "engagement_entry_task_update" ON "engagement_entries" AS PERMISSIVE FOR UPDATE TO public USING ("engagement_entries"."kind"='task' and exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.organization_id="engagement_entries"."organization_id" and e.project_id="engagement_entries"."project_id" and (exists(select 1 from memberships m where m.organization_id=e.organization_id and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member')) or (e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status in ('Active') and e.payload->>'contractStatus'='Confirmed' and e.payload->>'companyAgreed'='true' and e.payload->>'expertAgreed'='true' and e.payload->>'conflictStatus'='Cleared' and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status='Verified') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now())))) and exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.status='Active')) WITH CHECK ("engagement_entries"."kind"='task' and exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.organization_id="engagement_entries"."organization_id" and e.project_id="engagement_entries"."project_id" and (exists(select 1 from memberships m where m.organization_id=e.organization_id and m.user_id=(select current_setting('borderless.user_id',true)) and m.role in ('Owner','Admin','Member')) or (e.expert_user_id=(select current_setting('borderless.user_id',true)) and e.status in ('Active') and e.payload->>'contractStatus'='Confirmed' and e.payload->>'companyAgreed'='true' and e.payload->>'expertAgreed'='true' and e.payload->>'conflictStatus'='Cleared' and exists(select 1 from expert_profiles p where p.id=e.expert_id and p.user_id=(select current_setting('borderless.user_id',true)) and p.status='Verified') and e.revoked_at is null and (e.access_expires_at is null or e.access_expires_at>now())))) and exists(select 1 from engagements e where e.id="engagement_entries"."engagement_id" and e.status='Active'));